<?php declare( strict_types=1 ); namespace Amanah\SEOEngine\AI\Provider; use Amanah\SEOEngine\AI\AIRequest; use Amanah\SEOEngine\AI\AIResponse; use Amanah\SEOEngine\Infrastructure\Http\HttpClientInterface; defined( 'ABSPATH' ) || exit; final class OpenAIProvider implements AIProviderInterface { private $http; public function __construct(HttpClientInterface $http){$this->http=$http;} public function getProviderIdentifier(): string{return 'openai';} public function getProviderName(): string{return 'OpenAI';} public function getCapabilities(): array{return array(ProviderCapabilities::TEXT_GENERATION,ProviderCapabilities::STRUCTURED_OUTPUT,ProviderCapabilities::MODEL_DISCOVERY,ProviderCapabilities::USAGE_REPORTING);} public function validateCredentials(array $c): array{if(!isset($c['api_key'])||''===trim((string)$c['api_key']))return array('valid'=>false,'category'=>'authentication_error');$r=$this->http->request('GET','https://api.openai.com/v1/models',array('headers'=>array('Authorization'=>'Bearer '.$c['api_key']),'timeout'=>15));if(is_wp_error($r))return array('valid'=>false,'category'=>'network_error');$code=(int)wp_remote_retrieve_response_code($r);if($code<200||$code>=300)return array('valid'=>false,'category'=>$this->normalizeError($r)['category']);$b=json_decode(wp_remote_retrieve_body($r),true);return array('valid'=>is_array($b)&&isset($b['data'])&&is_array($b['data']),'category'=>(is_array($b)&&isset($b['data'])&&is_array($b['data']))?null:'provider_unavailable_error');} public function discoverModels(array $c): array{$r=$this->http->request('GET','https://api.openai.com/v1/models',array('headers'=>array('Authorization'=>'Bearer '.$c['api_key']),'timeout'=>15));if(is_wp_error($r))throw new \RuntimeException('network_error');$code=(int)wp_remote_retrieve_response_code($r);if($code<200||$code>=300)throw new \RuntimeException($this->normalizeError($r)['category']);$b=json_decode(wp_remote_retrieve_body($r),true);if(!is_array($b)||!isset($b['data'])||!is_array($b['data']))throw new \RuntimeException('provider_unavailable_error');$o=array();foreach($b['data'] as $m)if(isset($m['id']))$o[]=array('model_identifier'=>(string)$m['id'],'display_name'=>(string)$m['id'],'capabilities'=>$this->getCapabilities());return $o;} public function generate(AIRequest $q,array $c): AIResponse{$p=array('model'=>$q->getModel(),'input'=>$q->getPrompt().(empty($q->getContext())?'':"\n\nContext:\n".wp_json_encode($q->getContext())));if($q->isStructured())$p['text']=array('format'=>array('type'=>'json_object'));$r=$this->http->request('POST','https://api.openai.com/v1/responses',array('headers'=>array('Authorization'=>'Bearer '.$c['api_key'],'Content-Type'=>'application/json'),'body'=>wp_json_encode($p),'timeout'=>60));if(is_wp_error($r))throw new \RuntimeException('network_error');if((int)wp_remote_retrieve_response_code($r)>=400)throw new \RuntimeException($this->normalizeError($r)['category']);$b=json_decode(wp_remote_retrieve_body($r),true);$rawUsage=$b['usage']??array();$u=isset($b['usage'])?array('input_tokens'=>$rawUsage['input_tokens']??null,'output_tokens'=>$rawUsage['output_tokens']??null,'total_tokens'=>$rawUsage['total_tokens']??null,'usage_status'=>'reported'):array('usage_status'=>'unknown');if(isset($rawUsage['estimated_cost'])&&is_numeric($rawUsage['estimated_cost'])){$u['estimated_cost']=(float)$rawUsage['estimated_cost'];$u['currency']=isset($rawUsage['currency'])?(string)$rawUsage['currency']:null;$u['pricing_source']=isset($rawUsage['pricing_source'])?(string)$rawUsage['pricing_source']:'provider_reported';}return new AIResponse('openai',$q->getModel(),(string)($b['output_text']??''),$u,is_array($b)?$b:array());} public function normalizeError($r): array{$c=is_wp_error($r)?'network_error':(int)wp_remote_retrieve_response_code($r);if(401===$c||403===$c)return array('category'=>'authentication_error');if(404===$c)return array('category'=>'invalid_model_error');if(429===$c)return array('category'=>'rate_limit_error');if(408===$c||$